// Valida y normaliza la query entrante
const body = $input.item.json.body || $input.item.json;
const query = (body.query || '').trim();
const topK = body.top_k || 3;
const categoria = body.categoria || null; // opcional: filtrar por 'presencia', 'empleado', etc.

if (!query) {
  throw new Error('El campo "query" es obligatorio');
}

return { query, top_k: topK, categoria };

// Prepara el embedding y los parametros para Postgres
const params = $('Validar query').item.json;
const embeddingResp = $input.item.json;
const embedding = embeddingResp.data?.[0]?.embedding;

if (!embedding) {
  throw new Error('No se pudo generar embedding de la query');
}

return {
  query: params.query,
  top_k: params.top_k,
  categoria: params.categoria,
  embedding_str: '[' + embedding.join(',') + ']'
};

// Reformatea la respuesta como array de objetos para mejor lectura
const arr = $input.item.json;
const keys = ['id', 'slug', 'categoria', 'nombre', 'descripcion_corta', 'descripcion_larga', 'precio_setup', 'precio_recurrente', 'tiempo_entrega', 'entregables', 'casos_uso', 'prerequisitos', 'similarity'];
const length = (arr.id || []).length;

const resultados = [];
for (let i = 0; i < length; i++) {
  const r = {};
  keys.forEach(k => { r[k] = arr[k]?.[i]; });
  resultados.push(r);
}

const query = $('Validar query').item.json.query;

return {
  ok: true,
  query,
  total: resultados.length,
  resultados
};
